  count = count + 1
  local code = FourCC(id)
  local label = GetAbilitySoundById(code, E)
  local looped = GetAbilitySoundById(code, L)
  if label ~= "" or looped ~= "" then withLabel = withLabel + 1 end
  for _, text in ipairs({ id, GetObjectName(code) or "", label, label:lower(), looped }) do
    for _, kind in ipairs({ E, L }) do
      asked = asked + 1
      local answer = GetAbilitySound(text, kind)
      if answer ~= "" and #hits < 6 then hits[#hits + 1] = id .. " [" .. text .. "] " .. answer end
    end
  end
end
out("ids " .. count .. " with a by-id sound label " .. withLabel)
out("asked " .. asked .. " answered something " .. #hits)
for _, hit in ipairs(hits) do out("answer " .. hit) end
done()
